impl Solution {
    pub fn count_routes(locations: Vec<i32>, start: i32, finish: i32, fuel: i32) -> i32 {
        const MOD: i32 = 1_000_000_007;
        let n = locations.len() as i32;
        let mut dp = vec![vec![vec![vec![0; n as usize]; fuel as usize + 1]; n as usize]; n as usize];

        dp[start as usize][0][fuel as usize] = 1;

        for j in 0..n {
            for city in 0..n {
                for remaining_fuel in 0..=fuel {
                    if dp[city as usize][j as usize][remaining_fuel as usize] == 0 {
                        continue;
                    }
                    if city == finish {
                        continue;
                    }
                    for next_city in j..n {
                        let cost = (locations[city as usize] as i32 - locations[next_city as usize] as i32).abs();
                        if cost > 0 && cost <= remaining_fuel {
                            let new_fuel = remaining_fuel - cost;
                            dp[next_city as usize][next_city as usize][new_fuel as usize] =
                                (dp[next_city as usize][next_city as usize][new_fuel as usize] + dp[city as usize][j as usize][remaining_fuel as usize]) % MOD;
                        }
                    }
                    if j + 1 < n {
                        dp[city as usize][(j + 1) as usize][remaining_fuel as usize] =
                            (dp[city as usize][(j + 1) as usize][remaining_fuel as usize] + dp[city as usize][j as usize][remaining_fuel as usize]) % MOD;
                    }
                }
            }
        }

        let mut result = 0;
        for j in 0..n {
            for remaining_fuel in 0..=fuel {
                if dp[finish as usize][j as usize][remaining_fuel as usize] > 0 {
                    result = (result + dp[finish as usize][j as usize][remaining_fuel as usize]) % MOD;
                }
            }
        }

        result
    }
}

